function publicHttpsUrl(value) {
	try {
		const url = new URL(value);
		return url.protocol === "https:" && !url.username && !url.password ? url : null;
	} catch {
		return null;
	}
}
function websiteVideo(value) {
	const url = publicHttpsUrl(value);
	if (!url) return null;
	let youtube = "";
	if (url.hostname === "youtu.be") youtube = url.pathname.slice(1);
	if ([
		"youtube.com",
		"www.youtube.com",
		"www.youtube-nocookie.com"
	].includes(url.hostname)) youtube = url.pathname === "/watch" ? url.searchParams.get("v") || "" : url.pathname.match(/^\/(?:embed|shorts)\/([^/]+)$/)?.[1] || "";
	if (/^[\w-]{11}$/.test(youtube)) return {
		kind: "embed",
		url: `https://www.youtube-nocookie.com/embed/${youtube}`
	};
	if ([
		"vimeo.com",
		"www.vimeo.com",
		"player.vimeo.com"
	].includes(url.hostname)) {
		const id = url.pathname.match(/^\/(?:video\/)?(\d+)$/)?.[1];
		if (id) return {
			kind: "embed",
			url: `https://player.vimeo.com/video/${id}`
		};
	}
	if (/\.(mp4|webm)$/i.test(url.pathname)) return {
		kind: "file",
		url: url.href
	};
	return null;
}
